const std = @import("std");
fn testWith(b: *std.Build, runner: std.Build.LazyPath, options: std.Build.TestOptions) *std.Build.Step.Compile { var configured = options; configured.test_runner = .{ .path = runner, .mode = .server }; return b.addTest(configured); }
pub fn build(b: *std.Build) void { const target = b.standardTargetOptions(.{}); const optimize = b.standardOptimizeOption(.{}); const dep = b.dependency("zigeffect_std", .{ .target = target, .optimize = optimize }); const module = b.addModule("zigeffect_redis", .{ .root_source_file = b.path("src/root.zig"), .target = target, .optimize = optimize, .imports = &.{.{ .name = "zigeffect_std", .module = dep.module("zigeffect_std") }} }); const tests = testWith(b, dep.module("zigeffect_test_runner").root_source_file.?, .{ .name = "zigeffect-redis-tests", .root_module = module }); b.step("test", "Run Redis adapter tests").dependOn(&b.addRunArtifact(tests).step); const host = b.option([]const u8, "host", "Redis conformance host") orelse "127.0.0.1"; const port = b.option(u16, "port", "Redis conformance port") orelse 16379; const options = b.addOptions(); options.addOption([]const u8, "host", host); options.addOption(u16, "port", port); const live_module = b.createModule(.{ .root_source_file = b.path("tests/live_conformance.zig"), .target = target, .optimize = optimize, .imports = &.{ .{ .name = "zigeffect_redis", .module = module }, .{ .name = "live_options", .module = options.createModule() } } }); const live = testWith(b, dep.module("zigeffect_test_runner").root_source_file.?, .{ .name = "zigeffect-redis-live", .root_module = live_module }); b.step("conformance", "Run live Redis conformance").dependOn(&b.addRunArtifact(live).step); }
